// Prepare email requests for each portfolio company
const portfolioCompanies = $input.item.json;
const today = new Date();
const lastMonth = new Date(today.getFullYear(), today.getMonth() - 1, 1);
const lastMonthName = lastMonth.toLocaleString('default', { month: 'long' });
const lastMonthYear = lastMonth.getFullYear();

// Create an array of items for each portfolio company
const companyItems = [];

for (const company of portfolioCompanies) {
  // Skip if no email contact
  if (!company.ceoEmail && !company.cfoEmail && !company.reportingContact) {
    continue;
  }

  // Determine reporting contact
  const reportingEmail = company.reportingContact || company.cfoEmail || company.ceoEmail;

  // Create reporting item
  companyItems.push({
    json: {
      companyId: company.id,
      companyName: company.name,
      stage: company.stage,
      sector: company.sector,
      investmentDate: company.investmentDate,
      investmentAmount: company.investmentAmount,
      ownership: company.ownership,
      reportingEmail: reportingEmail,
      ccEmails: [company.ceoEmail, company.cfoEmail].filter(email => email && email !== reportingEmail),
      lastReportMonth: lastMonthName,
      lastReportYear: lastMonthYear,
      reportingPeriod: `${lastMonthName} ${lastMonthYear}`,
      reportDueDate: new Date(today.getFullYear(), today.getMonth(), 15).toISOString(),
      reportStatus: 'Requested',
      lastUpdated: new Date().toISOString()
    }
  });
}

return companyItems;

