// Process report submission data
const reportData = $input.item.json;

// Calculate key metrics
const profit = reportData.revenue - reportData.expenses;
const profitMargin = reportData.revenue > 0 ? (profit / reportData.revenue) * 100 : 0;
const burnRate = reportData.expenses - reportData.revenue;

// Format reporting period
const reportingPeriod = reportData.reportingPeriod.trim();

// Add calculated fields and metadata
const processedReport = {
  ...reportData,
  profit,
  profitMargin,
  burnRate,
  submissionDate: new Date().toISOString(),
  reportStatus: 'Submitted',
  reviewStatus: 'Pending Review',
  hasFinancials: !!reportData.financialStatements,
  financialUrl: reportData.financialStatements || '',
  lastUpdated: new Date().toISOString()
};

return { json: processedReport };

// Combine report data with company details
const reportData = $input.first().json;
const companyData = $input.last().json;

// Create combined data object
const combinedData = {
  ...reportData,
  companyId: companyData.id,
  stage: companyData.stage,
  sector: companyData.sector,
  investmentDate: companyData.investmentDate,
  investmentAmount: companyData.investmentAmount,
  ownership: companyData.ownership,
  portfolioManager: companyData.portfolioManager,
  boardSeat: companyData.boardSeat === 'Yes',
  lastValuation: companyData.lastValuation
};

// Calculate performance metrics
const monthsSinceInvestment = Math.floor((new Date() - new Date(companyData.investmentDate)) / (30 * 24 * 60 * 60 * 1000));
const revenueGrowth = companyData.lastReportedRevenue ? ((reportData.revenue - companyData.lastReportedRevenue) / companyData.lastReportedRevenue) * 100 : 0;
const customerGrowth = companyData.lastReportedCustomers ? ((reportData.customers - companyData.lastReportedCustomers) / companyData.lastReportedCustomers) * 100 : 0;

// Add performance metrics
combinedData.monthsSinceInvestment = monthsSinceInvestment;
combinedData.revenueGrowth = revenueGrowth;
combinedData.customerGrowth = customerGrowth;

// Add alert flags
combinedData.alerts = [];
if (reportData.runway < 6) {
  combinedData.alerts.push('Low Runway');
}
if (revenueGrowth < 0) {
  combinedData.alerts.push('Revenue Decline');
}
if (customerGrowth < 0) {
  combinedData.alerts.push('Customer Decline');
}
if (reportData.challenges && reportData.challenges.length > 100) {
  combinedData.alerts.push('Significant Challenges');
}

combinedData.alertCount = combinedData.alerts.length;
combinedData.alertsText = combinedData.alerts.join(', ');

return { json: combinedData };

