// Generate portfolio summary report
const reports = $input.item.json;

// Get reports from the last 30 days
const thirtyDaysAgo = new Date();
thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

const recentReports = reports.filter(report => {
  const submissionDate = new Date(report.submissionDate);
  return submissionDate >= thirtyDaysAgo;
});

// Group reports by company (keeping only the most recent for each)
const companiesMap = {};
for (const report of recentReports) {
  if (!companiesMap[report.companyId] || new Date(report.submissionDate) > new Date(companiesMap[report.companyId].submissionDate)) {
    companiesMap[report.companyId] = report;
  }
}

// Convert to array
const latestReports = Object.values(companiesMap);

// Calculate portfolio metrics
const totalRevenue = latestReports.reduce((sum, report) => sum + (parseFloat(report.revenue) || 0), 0);
const totalProfit = latestReports.reduce((sum, report) => sum + (parseFloat(report.profit) || 0), 0);
const totalCash = latestReports.reduce((sum, report) => sum + (parseFloat(report.cashBalance) || 0), 0);
const totalCustomers = latestReports.reduce((sum, report) => sum + (parseFloat(report.customers) || 0), 0);
const totalHeadcount = latestReports.reduce((sum, report) => sum + (parseFloat(report.headcount) || 0), 0);

// Calculate averages
const avgRunway = latestReports.reduce((sum, report) => sum + (parseFloat(report.runway) || 0), 0) / latestReports.length;
const avgRevenueGrowth = latestReports.reduce((sum, report) => sum + (parseFloat(report.revenueGrowth) || 0), 0) / latestReports.length;
const avgCustomerGrowth = latestReports.reduce((sum, report) => sum + (parseFloat(report.customerGrowth) || 0), 0) / latestReports.length;

// Count companies by stage
const stageCount = {};
for (const report of latestReports) {
  stageCount[report.stage] = (stageCount[report.stage] || 0) + 1;
}

// Count companies by sector
const sectorCount = {};
for (const report of latestReports) {
  sectorCount[report.sector] = (sectorCount[report.sector] || 0) + 1;
}

// Find companies with alerts
const companiesWithAlerts = latestReports.filter(report => report.alertCount > 0);

// Create summary report
const portfolioSummary = {
  reportDate: new Date().toISOString(),
  reportPeriod: `Last 30 days (${new Date(thirtyDaysAgo).toLocaleDateString()} - ${new Date().toLocaleDateString()})`,
  totalCompanies: latestReports.length,
  totalRevenue,
  totalProfit,
  totalCash,
  totalCustomers,
  totalHeadcount,
  avgRunway,
  avgRevenueGrowth,
  avgCustomerGrowth,
  stageDistribution: JSON.stringify(stageCount),
  sectorDistribution: JSON.stringify(sectorCount),
  companiesWithAlerts: companiesWithAlerts.length,
  alertCompanies: companiesWithAlerts.map(c => c.companyName).join(', '),
  lowRunwayCompanies: latestReports.filter(r => r.runway < 6).map(c => c.companyName).join(', '),
  highGrowthCompanies: latestReports.filter(r => r.revenueGrowth > 50).map(c => c.companyName).join(', ')
};

return { json: portfolioSummary };

