// Check for overdue reports
const pendingReports = $input.item.json;

// If no pending reports, return empty
if (!pendingReports) {
  return { json: { hasOverdueReports: false } };
}

// Check if report is overdue
const now = new Date();
const dueDate = new Date(pendingReports.reportDueDate);
const isOverdue = now > dueDate;

// Calculate days overdue
const daysOverdue = Math.floor((now - dueDate) / (24 * 60 * 60 * 1000));

// Determine if reminder should be sent
// Send reminder if 1 day overdue, 3 days overdue, or 7 days overdue
const shouldSendReminder = isOverdue && (daysOverdue === 1 || daysOverdue === 3 || daysOverdue === 7);

return {
  json: {
    ...pendingReports,
    isOverdue,
    daysOverdue,
    shouldSendReminder
  }
};
